 n; k++) {\n      // remove row i from queue k\n      i = w[head + k]\n      // count V(k,k) as nonzero\n      s.lnz++\n      // add a fictitious row\n      if (i < 0) { i = s.m2++ }\n      // associate row i with V(:,k)\n      pinv[i] = k\n      // skip if V(k+1:m,k) is empty\n      if (--nque[k] <= 0) { continue }\n      // nque[k] is nnz (V(k+1:m,k))\n      s.lnz += w[nque + k]\n      // move all rows to parent of k\n      const pa = parent[k]\n      if (pa !== -1) {\n        if (w[nque + pa] === 0) { w[tail + pa] = w[tail + k] }\n        w[next + w[tail + k]] = w[head + pa]\n        w[head + pa] = w[next + i]\n        w[nque + pa] += w[nque + k]\n      }\n    }\n    for (i = 0; i < m; i++) {\n      if (pinv[i] < 0) { pinv[i] = k++ }\n    }\n    return true\n  }\n})\n","/**\n * Permutes a sparse matrix C = P * A * Q\n *\n * @param {SparseMatrix}  a         The Matrix A\n * @param {Array}   pinv            The row permutation vector\n * @param {Array}   q               The column permutation vector\n * @param {boolean} values          Create a pattern matrix (false), values and pattern otherwise\n *\n * @return {Matrix}                 C = P * A * Q, null on error\n *\n * Reference: http://faculty.cse.tamu.edu/davis/publications.html\n */\nexport function csPermute (a, pinv, q, values) {\n  // a arrays\n  const avalues = a._values\n  const aindex = a._index\n  const aptr = a._ptr\n  const asize = a._size\n  const adt = a._datatype\n  // rows & columns\n  const m = asize[0]\n  const n = asize[1]\n  // c arrays\n  const cvalues = values && a._values ? [] : null\n  const cindex = [] // (aptr[n])\n  const cptr = [] // (n + 1)\n  // initialize vars\n  let nz = 0\n  // loop columns\n  for (let k = 0; k < n; k++) {\n    // column k of C is column q[k] of A\n    cptr[k] = nz\n    // apply column permutation\n    const j = q ? (q[k]) : k\n    // loop values in column j of A\n    for (let t0 = aptr[j], t1 = aptr[j + 1], t = t0; t < t1; t++) {\n      // row i of A is row pinv[i] of C\n      const r = pinv ? pinv[aindex[t]] : aindex[t]\n      // index\n      cindex[nz] = r\n      // check we need to populate values\n      if (cvalues) { cvalues[nz] = avalues[t] }\n      // increment number of nonzero elements\n      nz++\n    }\n  }\n  // finalize the last column of C\n  cptr[n] = nz\n  // return C matrix\n  return a.createSparseMatrix({\n    values: cvalues,\n    index: cindex,\n    ptr: cptr,\n    size: [m, n],\n    datatype: adt\n  })\n}\n","/**\n * Computes the elimination tree of Matrix A (using triu(A)) or the\n * elimination tree of A'A without forming A'A.\n *\n * @param {Matrix}  a               The A Matrix\n * @param {boolean} ata             A value of true the function computes the etree of A'A\n *\n * Reference: http://faculty.cse.tamu.edu/davis/publications.html\n */\nexport function csEtree (a, ata) {\n  // check inputs\n  if (!a) { return null }\n  // a arrays\n  const aindex = a._index\n  const aptr = a._ptr\n  const asize = a._size\n  // rows & columns\n  const m = asize[0]\n  const n = asize[1]\n\n  // allocate result\n  const parent = [] // (n)\n\n  // allocate workspace\n  const w = [] // (n + (ata ? m : 0))\n  const ancestor = 0 // first n entries in w\n  const prev = n // last m entries (ata = true)\n\n  let i, inext\n\n  // check we are calculating A'A\n  if (ata) {\n    // initialize workspace\n    for (i = 0; i < m; i++) { w[prev + i] = -1 }\n  }\n  // loop columns\n  for (let k = 0; k < n; k++) {\n    // node k has no parent yet\n    parent[k] = -1\n    // nor does k have an ancestor\n    w[ancestor + k] = -1\n    // values in column k\n    for (let p0 = aptr[k], p1 = aptr[k + 1], p = p0; p < p1; p++) {\n      // row\n      const r = aindex[p]\n      // node\n      i = ata ? (w[prev + r]) : r\n      // traverse from i to k\n      for (; i !== -1 && i < k; i = inext) {\n        // inext = ancestor of i\n        inext = w[ancestor + i]\n        // path compression\n        w[ancestor + i] = k\n        // check no anc., parent is k\n        if (inext === -1) { parent[i] = k }\n      }\n      if (ata) { w[prev + r] = k }\n    }\n  }\n  return parent\n}\n","import { csTdfs } from './csTdfs.js'\n\n/**\n * Post order a tree of forest\n *\n * @param {Array}   parent          The tree or forest\n * @param {Number}  n               Number of columns\n *\n * Reference: http://faculty.cse.tamu.edu/davis/publications.html\n */\nexport function csPost (parent, n) {\n  // check inputs\n  if (!parent) { return null }\n  // vars\n  let k = 0\n  let j\n  // allocate result\n  const post = [] // (n)\n  // workspace, head: first n entries, next: next n entries, stack: last n entries\n  const w = [] // (3 * n)\n  const head = 0\n  const next = n\n  const stack = 2 * n\n  // initialize workspace\n  for (j = 0; j < n; j++) {\n    // empty linked lists\n    w[head + j] = -1\n  }\n  // traverse nodes in reverse order\n  for (j = n - 1; j >= 0; j--) {\n    // check j is a root\n    if (parent[j] === -1) { continue }\n    // add j to list of its parent\n    w[next + j] = w[head + parent[j]]\n    w[head + parent[j]] = j\n  }\n  // loop nodes\n  for (j = 0; j < n; j++) {\n    // skip j if it is not a root\n    if (parent[j] !== -1) { continue }\n    // depth-first search\n    k = csTdfs(j, k, w, head, next, post, stack)\n  }\n  return post\n}\n","/**\n * Checks if the node at w[j] is marked\n *\n * @param {Array}   w               The array\n * @param {Number}  j               The array index\n *\n * Reference: http://faculty.cse.tamu.edu/davis/publications.html\n */\nexport function csMarked (w, j) {\n  // check node is marked\n  return w[j] < 0\n}\n","import { csFlip } from './csFlip.js'\n\n/**\n * Marks the node at w[j]\n *\n * @param {Array}   w               The array\n * @param {Number}  j               The array index\n *\n * Reference: http://faculty.cse.tamu.edu/davis/publications.html\n */\nexport function csMark (w, j) {\n  // mark w[j]\n  w[j] = csFlip(w[j])\n}\n","import { csFlip } from './csFlip.js'\n\n/**\n * Flips the value if it is negative of returns the same value otherwise.\n *\n * @param {Number}  i               The value to flip\n *\n * Reference: http://faculty.cse.tamu.edu/davis/publications.html\n */\nexport function csUnflip (i) {\n  // flip the value if it is negative\n  return i < 0 ? csFlip(i) : i\n}\n","import { csMarked } from './csMarked.js'\nimport { csMark } from './csMark.js'\nimport { csUnflip } from './csUnflip.js'\n\n/**\n * Depth-first search computes the nonzero pattern xi of the directed graph G (Matrix) starting\n * at nodes in B (see csReach()).\n *\n * @param {Number}  j               The starting node for the DFS algorithm\n * @param {Matrix}  g               The G matrix to search, ptr array modified, then restored\n * @param {Number}  top             Start index in stack xi[top..n-1]\n * @param {Number}  k               The kth column in B\n * @param {Array}   xi              The nonzero pattern xi[top] .. xi[n - 1], an array of size = 2 * n\n *                                  The first n entries is the nonzero pattern, the last n entries is the stack\n * @param {Array}   pinv            The inverse row permutation vector, must be null for L * x = b\n *\n * @return {Number}                 New value of top\n *\n * Reference: http://faculty.cse.tamu.edu/davis/publications.html\n */\nexport function csDfs (j, g, top, xi, pinv) {\n  // g arrays\n  const index = g._index\n  const ptr = g._ptr\n  const size = g._size\n  // columns\n  const n = size[1]\n  // vars\n  let i, p, p2\n  // initialize head\n  let head = 0\n  // initialize the recursion stack\n  xi[0] = j\n  // loop\n  while (head >= 0) {\n    // get j from the top of the recursion stack\n    j = xi[head]\n    // apply permutation vector\n    const jnew = pinv ? pinv[j] : j\n    // check node j is marked\n    if (!csMarked(ptr, j)) {\n      // mark node j as visited\n      csMark(ptr, j)\n      // update stack (last n entries in xi)\n      xi[n + head] = jnew < 0 ? 0 : csUnflip(ptr[jnew])\n    }\n    // node j done if no unvisited neighbors\n    let done = 1\n    // examine all neighbors of j, stack (last n entries in xi)\n    for (p = xi[n + head], p2 = jnew < 0 ? 0 : csUnflip(ptr[jnew + 1]); p < p2; p++) {\n      // consider neighbor node i\n      i = index[p]\n      // check we have visited node i, skip it\n      if (csMarked(ptr, i)) { continue }\n      // pause depth-first search of node j, update stack (last n entries in xi)\n      xi[n + head] = p\n      // start dfs at node i\n      xi[++head] = i\n      // node j is not done\n      done = 0\n      // break, to start dfs(i)\n      break\n    }\n    // check depth-first search at node j is done\n    if (done) {\n      // remove j from the recursion stack\n      head--\n      // and place in the output stack\n      xi[--top] = j\n    }\n  }\n  return top\n}\n","import { csReach } from './csReach.js'\nimport { factory } from '../../../utils/factory.js'\n\nconst name = 'csSpsolve'\nconst dependencies = [\n  'divideScalar',\n  'multiply',\n  'subtract'\n]\n\nexport const createCsSpsolve = /* #__PURE__ */ factory(name, dependencies, ({ divideScalar, multiply, subtract }) => {\n  /**\n   * The function csSpsolve() computes the solution to G * x = bk, where bk is the\n   * kth column of B. When lo is true, the function assumes G = L is lower triangular with the\n   * diagonal entry as the first entry in each column. When lo is true, the function assumes G = U\n   * is upper triangular with the diagonal entry as the last entry in each column.\n   *\n   * @param {Matrix}  g               The G matrix\n   * @param {Matrix}  b               The B matrix\n   * @param {Number}  k               The kth column in B\n   * @param {Array}   xi              The nonzero pattern xi[top] .. xi[n - 1], an array of size = 2 * n\n   *                                  The first n entries is the nonzero pattern, the last n entries is the stack\n   * @param {Array}   x               The soluton to the linear system G * x = b\n   * @param {Array}   pinv            The inverse row permutation vector, must be null for L * x = b\n   * @param {boolean} lo              The lower (true) upper triangular (false) flag\n   *\n   * @return {Number}                 The index for the nonzero pattern\n   *\n   * Reference: http://faculty.cse.tamu.edu/davis/publications.html\n   */\n  return function csSpsolve (g, b, k, xi, x, pinv, lo) {\n    // g arrays\n    const gvalues = g._values\n    const gindex = g._index\n    const gptr = g._ptr\n    const gsize = g._size\n    // columns\n    const n = gsize[1]\n    // b arrays\n    const bvalues = b._values\n    const bindex = b._index\n    const bptr = b._ptr\n    // vars\n    let p, p0, p1, q\n    // xi[top..n-1] = csReach(B(:,k))\n    const top = csReach(g, b, k, xi, pinv)\n    // clear x\n    for (p = top; p < n; p++) { x[xi[p]] = 0 }\n    // scatter b\n    for (p0 = bptr[k], p1 = bptr[k + 1], p = p0; p < p1; p++) { x[bindex[p]] = bvalues[p] }\n    // loop columns\n    for (let px = top; px < n; px++) {\n      // x array index for px\n      const j = xi[px]\n      // apply permutation vector (U x = b), j maps to column J of G\n      const J = pinv ? pinv[j] : j\n      // check column J is empty\n      if (J < 0) { continue }\n      // column value indeces in G, p0 <= p < p1\n      p0 = gptr[J]\n      p1 = gptr[J + 1]\n      // x(j) /= G(j,j)\n      x[j] = divideScalar(x[j], gvalues[lo ? p0 : (p1 - 1)])\n      // first entry L(j,j)\n      p = lo ? (p0 + 1) : p0\n      q = lo ? (p1) : (p1 - 1)\n      // loop\n      for (; p < q; p++) {\n        // row\n        const i = gindex[p]\n        // x(i) -= G(i,j) * x(j)\n        x[i] = subtract(x[i], multiply(gvalues[p], x[j]))\n      }\n    }\n    // return top of stack\n    return top\n  }\n})\n","import { csMarked } from './csMarked.js'\nimport { csMark } from './csMark.js'\nimport { csDfs } from './csDfs.js'\n\n/**\n * The csReach function computes X = Reach(B), where B is the nonzero pattern of the n-by-1\n * sparse column of vector b. The function returns the set of nodes reachable from any node in B. The\n * nonzero pattern xi of the solution x to the sparse linear system Lx=b is given by X=Reach(B).\n *\n * @param {Matrix}  g               The G matrix\n * @param {Matrix}  b               The B matrix\n * @param {Number}  k               The kth column in B\n * @param {Array}   xi              The nonzero pattern xi[top] .. xi[n - 1], an array of size = 2 * n\n *                                  The first n entries is the nonzero pattern, the last n entries is the stack\n * @param {Array}   pinv            The inverse row permutation vector\n *\n * @return {Number}                 The index for the nonzero pattern\n *\n * Reference: http://faculty.cse.tamu.edu/davis/publications.html\n */\nexport function csReach (g, b, k, xi, pinv) {\n  // g arrays\n  const gptr = g._ptr\n  const gsize = g._size\n  // b arrays\n  const bindex = b._index\n  const bptr = b._ptr\n  // columns\n  const n = gsize[1]\n  // vars\n  let p, p0, p1\n  // initialize top\n  let top = n\n  // loop column indeces in B\n  for (p0 = bptr[k], p1 = bptr[k + 1], p = p0; p < p1; p++) {\n    // node i\n    const i = bindex[p]\n    // check node i is marked\n    if (!csMarked(gptr, i)) {\n      // start a dfs at unmarked node i\n      top = csDfs(i, g, top, xi, pinv)\n    }\n  }\n  // loop columns from top -> n - 1\n  for (p = top; p < n; p++) {\n    // restore G\n    csMark(gptr, xi[p])\n  }\n  return top\n}\n","import { factory } from '../../../utils/factory.js'\nimport { createCsSpsolve } from './csSpsolve.js'\n\nconst name = 'csLu'\nconst dependencies = [\n  'abs',\n  'divideScalar',\n  'multiply',\n  'subtract',\n  'larger',\n  'largerEq',\n  'SparseMatrix'\n]\n\nexport const createCsLu = /* #__PURE__ */ factory(name, dependencies, ({ abs, divideScalar, multiply, subtract, larger, largerEq, SparseMatrix }) => {\n  const csSpsolve = createCsSpsolve({ divideScalar, multiply, subtract })\n\n  /**\n   * Computes the numeric LU factorization of the sparse matrix A. Implements a Left-looking LU factorization\n   * algorithm that computes L and U one column at a tume. At the kth step, it access columns 1 to k-1 of L\n   * and column k of A. Given the fill-reducing column ordering q (see parameter s) computes L, U and pinv so\n   * L * U = A(p, q), where p is the inverse of pinv.\n   *\n   * @param {Matrix}  m               The A Matrix to factorize\n   * @param {Object}  s               The symbolic analysis from csSqr(). Provides the fill-reducing\n   *                                  column ordering q\n   * @param {Number}  tol             Partial pivoting threshold (1 for partial pivoting)\n   *\n   * @return {Number}                 The numeric LU factorization of A or null\n   *\n   * Reference: http://faculty.cse.tamu.edu/davis/publications.html\n   */\n  return function csLu (m, s, tol) {\n    // validate input\n    if (!m) { return null }\n    // m arrays\n    const size = m._size\n    // columns\n    const n = size[1]\n    // symbolic analysis result\n    let q\n    let lnz = 100\n    let unz = 100\n    // update symbolic analysis parameters\n    if (s) {\n      q = s.q\n      lnz = s.lnz || lnz\n      unz = s.unz || unz\n    }\n    // L arrays\n    const lvalues = [] // (lnz)\n    const lindex = [] // (lnz)\n    const lptr = [] // (n + 1)\n    // L\n    const L = new SparseMatrix({\n      values: lvalues,\n      index: lindex,\n      ptr: lptr,\n      size: [n, n]\n    })\n    // U arrays\n    const uvalues = [] // (unz)\n    const uindex = [] // (unz)\n    const uptr = [] // (n + 1)\n    // U\n    const U = new SparseMatrix({\n      values: uvalues,\n      index: uindex,\n      ptr: uptr,\n      size: [n, n]\n    })\n    // inverse of permutation vector\n    const pinv = [] // (n)\n    // vars\n    let i, p\n    // allocate arrays\n    const x = [] // (n)\n    const xi = [] // (2 * n)\n    // initialize variables\n    for (i = 0; i < n; i++) {\n      // clear workspace\n      x[i] = 0\n      // no rows pivotal yet\n      pinv[i] = -1\n      // no cols of L yet\n      lptr[i + 1] = 0\n    }\n    // reset number of nonzero elements in L and U\n    lnz = 0\n    unz = 0\n    // compute L(:,k) and U(:,k)\n    for (let k = 0; k < n; k++) {\n      // update ptr\n      lptr[k] = lnz\n      uptr[k] = unz\n      // apply column permutations if needed\n      const col = q ? q[k] : k\n      // solve triangular system, x = L\\A(:,col)\n      const top = csSpsolve(L, m, col, xi, x, pinv, 1)\n      // find pivot\n      let ipiv = -1\n      let a = -1\n      // loop xi[] from top -> n\n      for (p = top; p < n; p++) {\n        // x[i] is nonzero\n        i = xi[p]\n        // check row i is not yet pivotal\n        if (pinv[i] < 0) {\n          // absolute value of x[i]\n          const xabs = abs(x[i])\n          // check absoulte value is greater than pivot value\n          if (larger(xabs, a)) {\n            // largest pivot candidate so far\n            a = xabs\n            ipiv = i\n          }\n        } else {\n          // x(i) is the entry U(pinv[i],k)\n          uindex[unz] = pinv[i]\n          uvalues[unz++] = x[i]\n        }\n      }\n      // validate we found a valid pivot\n      if (ipiv === -1 || a <= 0) { return null }\n      // update actual pivot column, give preference to diagonal value\n      if (pinv[col] < 0 && largerEq(abs(x[col]), multiply(a, tol))) { ipiv = col }\n      // the chosen pivot\n      const pivot = x[ipiv]\n      // last entry in U(:,k) is U(k,k)\n      uindex[unz] = k\n      uvalues[unz++] = pivot\n      // ipiv is the kth pivot row\n      pinv[ipiv] = k\n      // first entry in L(:,k) is L(k,k) = 1\n      lindex[lnz] = ipiv\n      lvalues[lnz++] = 1\n      // L(k+1:n,k) = x / pivot\n      for (p = top; p < n; p++) {\n        // row\n        i = xi[p]\n        // check x(i) is an entry in L(:,k)\n        if (pinv[i] < 0) {\n          // save unpermuted row in L\n          lindex[lnz] = i\n          // scale pivot column\n          lvalues[lnz++] = divideScalar(x[i], pivot)\n        }\n        // x[0..n-1] = 0 for next k\n        x[i] = 0\n      }\n    }\n    // update ptr\n    lptr[n] = lnz\n    uptr[n] = unz\n    // fix row indices of L for final pinv\n    for (p = 0; p < lnz; p++) { lindex[p] = pinv[lindex[p]] }\n    // trim arrays\n    lvalues.splice(lnz, lvalues.length - lnz)\n    lindex.splice(lnz, lindex.length - lnz)\n    uvalues.splice(unz, uvalues.length - unz)\n    uindex.splice(unz, uindex.length - unz)\n    // return LU factor\n    return { L, U, pinv }\n  }\n})\n","import { isInteger } from '../../../utils/number.js'\nimport { factory } from '../../../utils/factory.js'\nimport { createCsSqr } from '../sparse/csSqr.js'\nimport { createCsLu } from '../sparse/csLu.js'\n\nconst name = 'slu'\nconst dependencies = [\n  'typed',\n  'abs',\n  'add',\n  'multiply',\n  'transpose',\n  'divideScalar',\n  'subtract',\n  'larger',\n  'largerEq',\n  'SparseMatrix'\n]\n\nexport const createSlu = /* #__PURE__ */ factory(name, dependencies, ({ typed, abs, add, multiply, transpose, divideScalar, subtract, larger, largerEq, SparseMatrix }) => {\n  const csSqr = createCsSqr({ add, multiply, transpose })\n  const csLu = createCsLu({ abs, divideScalar, multiply, subtract, larger, largerEq, SparseMatrix })\n\n  /**\n   * Calculate the Sparse Matrix LU decomposition with full pivoting. Sparse Matrix `A` is decomposed in two matrices (`L`, `U`) and two permutation vectors (`pinv`, `q`) where\n   *\n   * `P * A * Q = L * U`\n   *\n   * Syntax:\n   *\n   *    math.slu(A, order, threshold)\n   *\n   * Examples:\n   *\n   *    const A = math.sparse([[4,3], [6, 3]])\n   *    math.slu(A, 1, 0.001)\n   *    // returns:\n   *    // {\n   *    //   L: [[1, 0], [1.5, 1]]\n   *    //   U: [[4, 3], [0, -1.5]]\n   *    //   p: [0, 1]\n   *    //   q: [0, 1]\n   *    // }\n   *\n   * See also:\n   *\n   *    lup, lsolve, usolve, lusolve\n   *\n   * @param {SparseMatrix} A              A two dimensional sparse matrix for which to get the LU decomposition.\n   * @param {Number}       order          The Symbolic Ordering and Analysis order:\n   *                                       0 - Natural ordering, no permutation vector q is returned\n   *                                       1 - Matrix must be square, symbolic ordering and analisis is performed on M = A + A'\n   *                                       2 - Symbolic ordering and analisis is performed on M = A' * A. Dense columns from A' are dropped, A recreated from A'.\n   *                                           This is appropriatefor LU factorization of unsymmetric matrices.\n   *                                       3 - Symbolic ordering and analisis is performed on M = A' * A. This is best used for LU factorization is matrix M has no dense rows.\n   *                                           A dense row is a row with more than 10*sqr(columns) entries.\n   * @param {Number}       threshold       Partial pivoting threshold (1 for partial pivoting)\n   *\n   * @return {Object} The lower triangular matrix, the upper triangular matrix and the permutation vectors.\n   */\n  return typed(name, {\n\n    'SparseMatrix, number, number': function (a, order, threshold) {\n      // verify order\n      if (!isInteger(order) || order < 0 || order > 3) { throw new Error('Symbolic Ordering and Analysis order must be an integer number in the interval [0, 3]') }\n      // verify threshold\n      if (threshold < 0 || threshold > 1) { throw new Error('Partial pivoting threshold must be a number from 0 to 1') }\n\n      // perform symbolic ordering and analysis\n      const s = csSqr(order, a, false)\n\n      // perform lu decomposition\n      const f = csLu(a, s, threshold)\n\n      // return decomposition\n      return {\n        L: f.L,\n        U: f.U,\n        p: f.pinv,\n        q: s.q,\n        toString: function () {\n          return 'L: ' + this.L.toString() + '\\nU: ' + this.U.toString() + '\\np: ' + this.p.toString() + (this.q ? '\\nq: ' + this.q.toString() : '') + '\\n'\n        }\n      }\n    }\n  })\n})\n","/**\n * Permutes a vector; x = P'b. In MATLAB notation, x(p)=b.\n *\n * @param {Array} p           The permutation vector of length n. null value denotes identity\n * @param {Array} b           The input vector\n *\n * @return {Array}            The output vector x = P'b\n */\nexport function csIpvec (p, b) {\n  // vars\n  let k\n  const n = b.length\n  const x = []\n  // check permutation vector was provided, p = null denotes identity\n  if (p) {\n    // loop vector\n    for (k = 0; k < n; k++) {\n      // apply permutation\n      x[p[k]] = b[k]\n    }\n  } else {\n    // loop vector\n    for (k = 0; k < n; k++) {\n      // x[i] = b[i]\n      x[k] = b[k]\n    }\n  }\n  return x\n}\n","import { isArray, isMatrix } from '../../../utils/is.js'\nimport { factory } from '../../../utils/factory.js'\nimport { createSolveValidation } from './utils/solveValidation.js'\nimport { csIpvec } from '../sparse/csIpvec.js'\n\nconst name = 'lusolve'\nconst dependencies = [\n  'typed',\n  'matrix',\n  'lup',\n  'slu',\n  'usolve',\n  'lsolve',\n  'DenseMatrix'\n]\n\nexport const createLusolve = /* #__PURE__ */ factory(name, dependencies, ({ typed, matrix, lup, slu, usolve, lsolve, DenseMatrix }) => {\n  const solveValidation = createSolveValidation({ DenseMatrix })\n\n  /**\n   * Solves the linear system `A * x = b` where `A` is an [n x n] matrix and `b` is a [n] column vector.\n   *\n   * Syntax:\n   *\n   *    math.lusolve(A, b)     // returns column vector with the solution to the linear system A * x = b\n   *    math.lusolve(lup, b)   // returns column vector with the solution to the linear system A * x = b, lup = math.lup(A)\n   *\n   * Examples:\n   *\n   *    const m = [[1, 0, 0, 0], [0, 2, 0, 0], [0, 0, 3, 0], [0, 0, 0, 4]]\n   *\n   *    const x = math.lusolve(m, [-1, -1, -1, -1])        // x = [[-1], [-0.5]